def portal_card(name, region, description, url, image, extra='', action='Open portal', image_alt=None, image_size=(1440, 960), context=''):
    image_alt = image_alt or f'Screenshot of the {name} landing page'
    return f'''<article class="portal-card"><a class="portal-preview" href="{e(url, quote=True)}" aria-label="Open {e(name, quote=True)}"><img src="/assets/{image}" width="{image_size[0]}" height="{image_size[1]}" alt="{e(image_alt, quote=True)}" loading="lazy"></a><div class="portal-copy"><span class="tag">{region}</span><h3>{name}</h3>{project_context(context)}<p>{description}</p><div class="project-links">{link(action,url,external=True)}{link('View screenshot','/assets/'+image,external=True)}{extra}</div></div></article>'''

