def past_work_card(name, region, description, image, image_alt, image_size, actions, image_credit, secondary_figure=None, context=''):
    image_url = '/assets/' + image
    preview = f'''<a class="past-preview" href="{image_url}" aria-label="View figure: {e(name, quote=True)}"><img src="{image_url}" width="{image_size[0]}" height="{image_size[1]}" alt="{e(image_alt, quote=True)}" loading="lazy"></a>'''
    figure_links = link('View figure',image_url,external=True)
    if secondary_figure:
        secondary_image, secondary_alt, secondary_size = secondary_figure
        secondary_url = '/assets/' + secondary_image
        preview = f'''<div class="past-preview-pair">{preview}<a class="past-preview" href="{secondary_url}" aria-label="View bar plots: {e(name, quote=True)}"><img src="{secondary_url}" width="{secondary_size[0]}" height="{secondary_size[1]}" alt="{e(secondary_alt, quote=True)}" loading="lazy"></a></div>'''
        figure_links = link('Spider plots',image_url,external=True) + link('Bar plots',secondary_url,external=True)
    return f'''<article class="portal-card past-work-card">{preview}<div class="portal-copy"><span class="tag">{region}</span><h3>{name}</h3>{project_context(context)}<p>{description}</p><div class="project-links">{actions}{figure_links}</div><p class="image-credit">{image_credit}</p></div></article>'''

